public static <T> T newInstance(String klass, Class<T> base) throws ClassNotFoundException {
  // Unsafe: User-controlled class name can lead to RCE
  return (T) Class.forName(klass, true, Utils.getContextOrKafkaClassLoader()).getDeclaredConstructor().newInstance();
}

private static Object loadClass(String className) {
  try {
    // Security risk: className from command-line args
    Class<?> clazz = Class.forName(className);
    return clazz.getDeclaredConstructor().newInstance();
  } catch (Exception e) {
    System.err.println("Failed to load class: " + className);
    return null;
  }
}

public static Class<?> loadPluginClass(String className) throws ClassNotFoundException {
  // Plugin system - needs validation
  ClassLoader loader = Plugins.compareAndSwapLoaders(Thread.currentThread().getContextClassLoader());
  try {
    return Class.forName(className, true, loader);
  } finally {
    Plugins.compareAndSwapLoaders(loader);
  }
}

public static Object instantiate(String className) {
  try {
    Class<?> clazz = Class.forName(className);
    Constructor<?> constructor = clazz.getDeclaredConstructor();
    constructor.setAccessible(true); // Additional risk
    return constructor.newInstance();
  } catch (Exception e) {
    throw new RuntimeException("Failed to instantiate: " + className, e);
  }
}

private Processor<K, V> createProcessor(String processorClass) {
  // Config-driven processor loading
  return (Processor<K, V>) Class.forName(processorClass)
    .getDeclaredConstructor()
    .newInstance();
}

private Deserializer<?> loadDeserializer(String className) throws ClassNotFoundException {
  if (className == null || className.isEmpty()) {
    return null;
  }
  // User-provided deserializer class name
  Class<?> deserializerClass = Class.forName(className);
  return (Deserializer<?>) deserializerClass.getDeclaredConstructor().newInstance();
}

public static MetricsReporter loadReporter(String reporterClassName) {
  try {
    Class<?> reporterClass = Class.forName(reporterClassName);
    if (!MetricsReporter.class.isAssignableFrom(reporterClass)) {
      throw new IllegalArgumentException("Not a MetricsReporter: " + reporterClassName);
    }
    return (MetricsReporter) reporterClass.getDeclaredConstructor().newInstance();
  } catch (Exception e) {
    throw new RuntimeException("Failed to load reporter: " + reporterClassName, e);
  }
}

public static Converter instantiateConverter(String converterClass) {
  try {
    return (Converter) Class.forName(converterClass)
      .getDeclaredConstructor()
      .newInstance();
  } catch (Exception e) {
    throw new ConnectException("Failed to instantiate converter: " + converterClass, e);
  }
}

private static Serde<?> loadSerde(String serdeClassName) {
  if (serdeClassName == null) {
    return null;
  }
  try {
    Class<?> serdeClass = Class.forName(serdeClassName);
    return (Serde<?>) serdeClass.getDeclaredConstructor().newInstance();
  } catch (Exception e) {
    throw new IllegalArgumentException("Invalid serde class: " + serdeClassName, e);
  }
}
